DECLARE
    v_updated_count NUMBER := 0;
BEGIN
    FOR dept_rec IN (SELECT department_id, budget FROM departments WHERE status = 'ACTIVE') LOOP
        UPDATE departments
        SET budget = budget * 1.05
        WHERE department_id = dept_rec.department_id;

        v_updated_count := v_updated_count + 1;
    END LOOP;

    COMMIT;
    DBMS_OUTPUT.PUT_LINE('Successfully updated ' || v_updated_count || ' departments.');
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        DBMS_OUTPUT.PUT_LINE('Error updating department budgets: ' || SQLERRM);
        RAISE;
END;
